function useReveal() {
  const ref = useRef(null);
  const [vis, setVis] = useState(false);
  useEffect(() => {
    const el = ref.current; if (!el) return;
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) setVis(true); }, { threshold:0.08 });
    obs.observe(el); return () => obs.disconnect();
  }, []);
  return [ref, vis];
}

function Reveal({ children, delay=0, style={} }) {
  const [ref, vis] = useReveal();
  return (
    <div ref={ref} style={{ opacity:vis?1:0, transform:vis?"translateY(0)":"translateY(24px)", transition:`opacity 0.75s ease ${delay}s, transform 0.75s ease ${delay}s`, ...style }}>
      {children}
    </div>
  );
}

function Label({ children, center }) {
  return (
    <div style={{ display:"flex", alignItems:"center", gap:14, justifyContent:center?"center":"flex-start", fontSize:"0.58rem", letterSpacing:"0.38em", textTransform:"uppercase", color:C.gold, fontFamily:B, fontWeight:400, marginBottom:18 }}>
      {!center && <span style={{ width:34, height:1, background:C.gold, flexShrink:0 }} />}
      {children}
    </div>
  );
}

function PriceTag({ ngn, usd, featured }) {
  return (
    <div style={{ marginBottom:6 }}>
      <div style={{ fontFamily:D, fontSize:"2.6rem", fontWeight:300, color:featured?C.cream:C.brownDeep, lineHeight:1 }}>{ngn}</div>
      <div style={{ fontSize:"0.8rem", color:featured?"rgba(232,213,163,0.8)":C.gold, marginTop:5, letterSpacing:"0.05em", display:"flex", alignItems:"center", gap:6 }}>
        {usd}
        <span style={{ fontSize:"0.62rem", color:featured?"rgba(237,227,209,0.4)":C.brownLight }}>(approx. USD)</span>
      </div>
    </div>
  );
}

